"""
    Sorts a list using bubble sort algorithm

    Input: A list of integers
    Output: A list containing the same integers as the input, but sorted in
            ascending order

    Sorts by iterating through a list swapping values that are in the wrong order.
    Stops when it is impossible for unsorted elements to remain.
    """
def bubble_sort(array: Any) -> object {
    for z in range((len(array) - 1)) {
        for x in range((len(array) - 1)) {
            for y in range((len(array) - 1)) {
                if (array[x] > array[(x + 1)]) {
                    temp = array[x];
                    array[x] = array[(x + 1)];
                    array[(x + 1)] = temp;
                }
            }
        }
    }
    return array;
}

"""Computing the BF of a nested model, meaning computing the bf for the
    "null" hypothesis of a given model.

    Args:
        - models: a dict, keys are models names while values are dictionaries
            reporting prior and posterior probabilities for the "null".

    Returns:
        - bfs: a dictionary, bayes factor of the null for each model.
    """
def hp_testing_savage_dickey_ratio(models: Any) -> object {
    bfs = {};
    for (model_name, model_dict) in models.items() {
        bfs[model_name] = model_dict['posterior'] / model_dict['prior'];
    }
    return bfs;
}

